def test_register_idempotent(fresh_auth):
    """같은 토큰 두 번 등록해도 1개만."""
    a = _anon()
    payload = {"token": "ExponentPushToken[abc]", "platform": "ios"}
    for _ in range(2):
        client.post(
            "/api/v1/auth/me/push-token",
            headers=_h(a["access_token"]), json=payload,
        )
    r = client.get("/api/v1/auth/me/push-tokens", headers=_h(a["access_token"]))
    assert len(r.json()["tokens"]) == 1


