# ---- unregister ----
def test_unregister_success(fresh_auth):
    a = _anon()
    payload = {"token": "ExponentPushToken[abc]", "platform": "ios"}
    client.post(
        "/api/v1/auth/me/push-token",
        headers=_h(a["access_token"]), json=payload,
    )
    r = client.request("DELETE", 
        "/api/v1/auth/me/push-token",
        headers=_h(a["access_token"]), json=payload,
    )
    assert r.status_code == 200
    assert r.json()["removed"] is True
    r2 = client.get("/api/v1/auth/me/push-tokens", headers=_h(a["access_token"]))
    assert len(r2.json()["tokens"]) == 0


