def test_list_shows_fields(fresh_auth):
    a = _anon()
    client.post(
        "/api/v1/auth/me/push-token",
        headers=_h(a["access_token"]),
        json={"token": "ExponentPushToken[abc]", "platform": "android", "device_id": "device-1"},
    )
